{
  "title": "Discussion about working abroad in Slovakia and Austria",
  "topics": [
    {
      "id": "job-search",
      "title": "Job search experiences",
      "claims": [
        {
          "text": "Finding a job abroad was difficult but the speaker managed it within two months",
          "evidence": [17]
        },
        {
          "text": "The speaker sent about 100 job applications and received only three interview invitations",
          "evidence": [21]
        },
        {
          "text": "Candidates with 3 years of experience still receive few interview calls",
          "evidence": [23]
        },
        {
          "text": "Even candidates with little or no local language skills can sometimes be hired",
          "evidence": [29]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Language requirements for jobs",
      "claims": [
        {
          "text": "Approximately 95% of vacancies specify that a local language is required",
          "evidence": [26]
        },
        {
          "text": "Most companies request a B2 level language proficiency, sometimes B1, and usually do not require a certificate",
          "evidence": [46]
        },
        {
          "text": "In Austria, everyday communication is mainly in German, but many colleagues speak English",
          "evidence": [15, 47]
        }
      ]
    },
    {
      "id": "salary",
      "title": "Salary expectations and offers",
      "claims": [
        {
          "text": "The speaker’s salary was higher than minimum wage but still modest compared to expectations",
          "evidence": [37]
        },
        {
          "text": "Salaries in Europe are generally higher than in Ukraine, though many candidates do not focus on this factor",
          "evidence": [35]
        }
      ]
    },
    {
      "id": "living-abroad",
      "title": "Living abroad experiences",
      "claims": [
        {
          "text": "The speaker has been living in Slovakia for almost a year and does not know the local language well",
          "evidence": [43]
        },
        {
          "text": "The speaker lives with a partner who has been in Austria for over 10 years and sees Austria as the best choice among European countries",
          "evidence": [60]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Do you personally feel you will stay in Austria?",
      "evidence": [58]
    },
    {
      "text": "What salary range do you expect as a junior developer?",
      "evidence": [34]
    }
  ]
}
